    // TODO(translate): port src/ulid.c::ulidgen_r
    //  1. ulid[26] = 0 (NUL terminator, as in C).
    //  2. t = SystemTime::now() ms since UNIX_EPOCH (u64).
    //  3. for i in (0..10).rev(): if ulid[i] != B32_ALPHABET[(t % 32) as usize]
    //     { ulid[i] = ...; same = false; } t /= 32;   (same starts true)
    //  4. if same: walk buf = &mut ulid[10..] right-to-left;
    //     while buf[i] == b'Z' { buf[i] = b'0'; }
    //     - all 'Z' (i underflows): thread::sleep(Duration::from_nanos(1_234_567))
    //       then recurse ulidgen_r(ulid) and return.
    //     - else if buf[i] is in B32_ALPHABET: set to next alphabet char, return.
    //     - else (invalid char): fall through to re-randomize.
    //  5. else: let mut rnd = [0u8; 16];
