pub fn ulidgen_r(ulid: &mut [u8; 27]) {
    // 1. NUL terminator, as in C.
    ulid[26] = 0;

    // 2. Millisecond timestamp since the UNIX epoch.
    let t = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_millis() as u64;

    // 3. Encode the 10 most significant base-32 digits. `same` starts true
    //    and is cleared on any digit mismatch (C semantics).
    let mut same = true;
    let mut t = t;
    for i in (0..10).rev() {
        let d = B32_ALPHABET[(t % 32) as usize];
        if ulid[i] != d {
            ulid[i] = d;
            same = false;
        }
        t /= 32;
    }

