        while buf[i] == b'Z' {
            buf[i] = b'0';
            if i == 0 {
                // All 16 chars were 'Z': sleep and recurse (C behavior).
                std::thread::sleep(Duration::from_nanos(1_234_567));
                ulidgen_r(ulid);
                return;
            }
            i -= 1;
        }
        if buf[i] == b'Z' {
            // Handled above by the loop; unreachable, but keep the branch shape.
            unreachable!();
        }
        if B32_ALPHABET.contains(&buf[i]) {
            // Advance to the next alphabet character.
            let pos = B32_ALPHABET.iter().position(|&c| c == buf[i]).unwrap();
